import{_ as t,c as i,o as n,j as a,af as o,a as s,t as r}from"./chunks/framework.W5ZyBR1w.js";const S=JSON.parse('{"title":"安装客户端","description":"本章主要讲述 MSST-Net 客户端的安装方式与平台要求。","frontmatter":{"title":"安装客户端","description":"本章主要讲述 MSST-Net 客户端的安装方式与平台要求。"},"headers":[],"relativePath":"connect/install/client.md","filePath":"connect/install/client.md"}'),p={name:"connect/install/client.md"},h={id:"frontmatter-title",tabindex:"-1"};function c(l,e,d,m,f,u){return n(),i("div",null,[a("h1",h,[s(r(l.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),a("p",null,r(l.$frontmatter.description),1),e[1]||(e[1]=o('<h2 id="客户端组成" tabindex="-1">客户端组成 <a class="header-anchor" href="#客户端组成" aria-label="Permalink to “客户端组成”">​</a></h2><p>MSST-Net 客户端由以下部分组成：</p><ul><li><strong>客户端核心（Core）</strong>：负责网络连接与协议处理。</li><li><strong>客户端控制器（Controller）</strong>：负责客户端配置与管理。</li></ul><p>不同平台的安装方式可能有所不同。</p><hr><h2 id="安装方式" tabindex="-1">安装方式 <a class="header-anchor" href="#安装方式" aria-label="Permalink to “安装方式”">​</a></h2><p>MSST-Net 提供以下安装方式：</p><ul><li>使用客户端安装器（推荐）</li><li>手动安装</li></ul><hr><h2 id="使用客户端安装器-推荐" tabindex="-1">使用客户端安装器（推荐） <a class="header-anchor" href="#使用客户端安装器-推荐" aria-label="Permalink to “使用客户端安装器（推荐）”">​</a></h2><p>对于桌面端系统（Windows / Linux / macOS），推荐使用 <strong>MSST-Net 客户端安装器</strong>。</p><p>客户端安装器可自动完成以下操作：</p><ul><li>安装客户端核心</li><li>安装客户端控制器</li><li>安装平台依赖</li><li>初始化运行环境</li></ul><p>下载地址：</p><p><a href="https://github.com/MSST-Net-Developers/msst-net-client-installer/releases" target="_blank" rel="noreferrer">下载 MSST-Net 客户端安装器</a></p><hr><h2 id="手动安装" tabindex="-1">手动安装 <a class="header-anchor" href="#手动安装" aria-label="Permalink to “手动安装”">​</a></h2><p>如果您希望手动安装客户端，请下载客户端组件：</p><p><a href="https://github.com/MSST-Net-Developers/msst-net-client-release/releases" target="_blank" rel="noreferrer">下载 MSST-Net 客户端组件</a></p><hr><h2 id="桌面端安装" tabindex="-1">桌面端安装 <a class="header-anchor" href="#桌面端安装" aria-label="Permalink to “桌面端安装”">​</a></h2><p>桌面端系统包括：</p><ul><li>Windows</li><li>Linux</li><li>macOS</li></ul><p>安装时需要以下组件：</p><ul><li>客户端核心（通常以 <code>msst-net-client-core</code> 开头）</li><li>客户端控制器（通常以 <code>msst-net-client-controller</code> 开头）</li></ul><p>控制器版本选择请参考：</p><p><a href="/connect/install/controller">《控制器说明》</a></p><hr><h2 id="移动端安装" tabindex="-1">移动端安装 <a class="header-anchor" href="#移动端安装" aria-label="Permalink to “移动端安装”">​</a></h2><p>移动端系统（如 Android）使用 <strong>Compose</strong> 版控制器。</p><p>Compose 版控制器内置客户端核心，无需单独安装核心组件。</p><p>安装时仅需安装控制器。</p><p>控制器说明请参考：</p><p><a href="/connect/install/controller">《控制器说明》</a></p><hr><h2 id="平台说明" tabindex="-1">平台说明 <a class="header-anchor" href="#平台说明" aria-label="Permalink to “平台说明”">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><p>Windows 平台手动安装客户端核心时，需要额外安装 <strong>wintun</strong>。</p><p>请将 wintun 提供的 <code>.dll</code> 文件与客户端核心放置在同一目录。</p><p>下载地址：</p><p><a href="https://www.wintun.net/" target="_blank" rel="noreferrer">下载 wintun</a></p><hr><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>Linux 平台通常无需额外依赖。</p><p>如需后台运行，建议配置系统服务。</p><p>详见：</p><p><a href="/connect/install/service">《配置系统服务》</a></p><hr><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h3><p>macOS 平台通常无需额外依赖。</p><p>如需后台运行，建议配置系统服务。</p><p>详见：</p><p><a href="/connect/install/service">《配置系统服务》</a></p><hr><h2 id="安装验证" tabindex="-1">安装验证 <a class="header-anchor" href="#安装验证" aria-label="Permalink to “安装验证”">​</a></h2><p>安装完成后，建议进行以下检查：</p><ul><li>客户端核心是否能够正常启动</li><li>客户端控制器是否能够正常打开</li><li>控制器是否能够检测到客户端核心</li><li>是否成功生成设备 ID</li></ul><p>如果以上检查均通过，则表示客户端安装成功。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>完成客户端安装后，建议继续：</p><ul><li>配置系统服务（可选）</li><li>完成接入认证</li></ul><p>详见：</p><ul><li><a href="/connect/install/service">《配置系统服务》</a></li><li><a href="/connect/start">《新手教程》</a></li></ul>',64))])}const x=t(p,[["render",c]]);export{S as __pageData,x as default};
